package com.vynedam.stockai.service;
import com.vynedam.stockai.domain.Role; import com.vynedam.stockai.dto.AuthDtos.*; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.User; import com.vynedam.stockai.repository.UserRepository; import com.vynedam.stockai.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder passwords; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder p,JwtService j){users=u;passwords=p;jwt=j;} public AuthResponse register(RegisterRequest r){if(users.countByRole(Role.SUPER_ADMIN)>0)throw new ApiException(HttpStatus.FORBIDDEN,"REGISTRATION_CLOSED","Use the Super Admin user-management API to create users");var email=r.email().trim().toLowerCase();if(users.existsByEmailIgnoreCase(email))throw new ApiException(HttpStatus.CONFLICT,"DUPLICATE_RECORD","Email already registered");var u=new User();u.name=r.name().trim();u.email=email;u.passwordHash=passwords.encode(r.password());u.role=Role.SUPER_ADMIN;u.unitId=r.unitId();users.save(u);return response(u);} public AuthResponse login(LoginRequest r){var u=users.findByEmailIgnoreCase(r.email().trim()).filter(x->x.active).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Email or password is incorrect"));if(!passwords.matches(r.password(),u.passwordHash))throw new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Email or password is incorrect");return response(u);} private AuthResponse response(User u){return new AuthResponse(jwt.issue(u),"Bearer",new UserResponse(u.id,u.name,u.email,u.role,u.unitId));} }
